    private void BackTrack(List<int> candidates, int target,
                            int idx,
                            List<List<int>> result,
                            List<int> item) {

        if(target == 0) {
            result.Add(new List<int>(item));
            return;
        }

        if(target < 0 || idx >= candidates.Count) return;

        // Iterative Way
        for(int i = idx; i < candidates.Count; i++) {

            // skip duplicate
            if(i > idx && candidates[i] == candidates[i-1]) {
                continue;
            }

            item.Add(candidates[i]);
            BackTrack(candidates, target - candidates[i], i + 1, result, item);

            item.RemoveAt(item.Count - 1);
        }
    }
}
